function reynoldsRho(rho, v, L, mu){ rho=+rho; v=+v; L=+L; mu=+mu; if(!(rho>0)||!(mu>0)) return {error:'密度与动力黏度须为正'}; return rho*v*L/mu; }
function reynoldsNu(v, L, nu){ v=+v; L=+L; nu=+nu; if(!(nu>0)) return {error:'运动黏度须为正'}; return v*L/nu; }
function regime(re){ if(!(re>0)) return '无效'; if(re<2300) return '层流'; if(re<=4000) return '过渡流'; return '湍流'; }
var EXPORTS={reynoldsRho:reynoldsRho, reynoldsNu:reynoldsNu, regime:regime};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ReynoldsForgePure = EXPORTS; }
